    0x6f, 0x48, 0x06, 0x5b, 0x2b, 0x28, 0x40, 0x2e, 
    0x4e, 0x0b, 0x16, 0x31, 0x30, 0x56, 0x21, 0x6e,
    0x2d, 0x30, 0x4b, 0x1c, 0x10, 0x04, 0x3f, 0x18,
    0x41, 0x34
]

def try_xor_with_pattern(data, pattern):
    if len(data) < len(pattern):
        return None
    key = []
    # First find potential key by XORing with known pattern
    for i in range(len(pattern)):
        key.append(data[i] ^ pattern[i])

    # Try to decrypt the whole data with this key
    result = []
    for i in range(len(data)):
        result.append(data[i] ^ key[i % len(key)])

    try:
        text = bytes(result).decode('ascii')
        if all(32 <= c <= 126 for c in result): # Check if printable
            return text
    except:
        pass
    return None

def find_repeating_xor_key(data, max_key_len=8):
    for key_len in range(1, max_key_len + 1):
        # Try common CTF flag formats
        patterns = [
            b'flag{',
            b'FLAG{',
            b'ctf{',
            b'CTF{',
            b'csaw'
        ]

        for pattern in patterns:
            result = try_xor_with_pattern(data, pattern)
            if result and ('flag' in result.lower() or 'ctf' in result.lower()):
                print(f"Potential flag with key length {key_len}: {result}")

# Try ROX (rotate XOR) patterns
def try_rox(data):
    results = set()
    for rotation in range(8):
        for key in range(256):
            result = []
            prev = key
            for b in data:
                # ROX operation: rotate and XOR
                decrypted = b ^ prev
                result.append(decrypted)
                prev = (prev << rotation | prev >> (8-rotation)) & 0xFF

            try:
                text = bytes(result).decode('ascii')
                if 'flag' in text.lower() or 'ctf' in text.lower():
                    if all(32 <= c <= 126 for c in result):  # Check if printable
                        results.add(text)
            except:
                continue

    return results

# Try simple XOR with each byte
def try_single_byte_xor():
    for key in range(256):
        result = []
        for b in encrypted:
            result.append(b ^ key)
        try:
            text = bytes(result).decode('ascii')
            if 'flag' in text.lower() or 'ctf' in text.lower():
                if all(32 <= c <= 126 for c in result):
                    print(f"Found with key {hex(key)}: {text}")
        except:
            continue

# Try rolling XOR
def try_rolling_xor():
    for init_key in range(256):
        result = []
        prev = init_key
        for b in encrypted:
            decrypted = b ^ prev
            result.append(decrypted)
            prev = decrypted

        try:
            text = bytes(result).decode('ascii')
            if 'flag' in text.lower() or 'ctf' in text.lower():
                if all(32 <= c <= 126 for c in result):
                    print(f"Found with rolling XOR (init {hex(init_key)}): {text}")
        except:
            continue

print("[*] Trying repeating XOR patterns...")
find_repeating_xor_key(encrypted)

