from pwn import *
import string
import itertools

def analyze_xor_operations():
    # The initial data array from binary analysis
    initial_data = [
        0x3f, 0x42, 0x38, 0x5f, 0x7a, 0x57, 0x71, 0x74, 0x66, 0x44, 0x47, 0x32,
        0x3d, 0x16, 0x63, 0x1f, 0x12, 0x1a, 0x12, 0x5c, 0x2a, 0x03, 0x64, 0x1c,
        0x15, 0x40, 0x01, 0x3f, 0x4c, 0x02, 0x3a, 0x30, 0x1d, 0x7c, 0x69, 0x4d,
        0x19, 0x5f, 0x48, 0x5e, 0x20, 0x03, 0x17, 0x09, 0x52, 0x6b, 0x4c, 0x65,
        0x6f, 0x48, 0x06, 0x5b, 0x2b, 0x28, 0x40, 0x2e, 0x4e, 0x0b, 0x16, 0x31,
        0x30, 0x56, 0x21, 0x6e, 0x2d, 0x30, 0x4b, 0x1c, 0x10, 0x04, 0x3f, 0x18,
        0x41, 0x34
    ]

    def try_possible_xor_keys():
        potential_keys = []
        for k in range(256):
            decoded = bytes([b ^ k for b in initial_data])
            if all(c in string.printable.encode() for c in decoded):
                potential_keys.append(k)
        return potential_keys

    def attempt_multi_byte_xor(data, key_length):
        best_score = 0
        best_key = None
        best_decoded = None

        for i in range(key_length):
            block = data[i::key_length]
            frequencies = [0] * 256
            for byte in block:
                frequencies[byte] += 1

            max_freq = max(frequencies)
            most_common = frequencies.index(max_freq)
            if most_common ^ 0x20 in range(256):  # XOR with space character
                potential_key_byte = most_common ^ 0x20
                score = frequencies[most_common] / len(block)
                if score > best_score:
                    best_score = score
                    best_key = potential_key_byte

        return best_key if best_key is not None else 0

    def stage3_transform(data):
        result = bytearray(data)
        for i in range(5, len(result)):
            for j in range(300):
                result[i] = result[i] ^ ((j << 5) & 0xFF) ^ (result[i-5] == ord('n'))
        return bytes(result)

    print("Analyzing encrypted data...")
    hexdump(bytes(initial_data))

    # Apply stage 3 reverse transformation
    after_stage3 = stage3_transform(initial_data)
    print("\n[*] After stage 3 reverse:")
    hexdump(after_stage3)

    print("\nAnalyzing byte patterns...\n")

    # Count byte frequencies
    freq = {}
    for b in initial_data:
        freq[b] = freq.get(b, 0) + 1

    print("Most common bytes:")
    for b, count in sorted(freq.items(), key=lambda x: (-x[1], x[0]))[:10]:
        print(f"0x{b:02x}: {count} times")

    print("\nASCII printable regions:")
    current_printable = []
    for i, b in enumerate(initial_data):
        if 32 <= b <= 126:
            current_printable.append(chr(b))
        else:
            if current_printable:
                start = i - len(current_printable)
                print(f"Positions {start},{start+1},{start+2},{start+3}: {''.join(current_printable)}")
                current_printable = []

    # Try various 4-byte XOR keys based on patterns
    possible_keys = [
        0x563a4009, 0x4142434F, 0x46524F4D, 0x434F4445
    ]

    for key in possible_keys:
        key_bytes = key.to_bytes(4, 'little')
        decoded = bytearray()
        for i in range(len(initial_data)):
            decoded.append(initial_data[i] ^ key_bytes[i % 4])

        if b'flag' in decoded or b'csawctf' in decoded:
            print(f"\nPotential flag pattern found with key {key:08x}:")
            hexdump(decoded)

