from pwn import *
import string

def decrypt_all_stages():
    # Initial encrypted data from binary
    initial_data = [
        0x3f, 0x42, 0x38, 0x5f, 0x7a, 0x57, 0x71, 0x74, 0x66, 0x44, 0x47, 0x32,
        0x3d, 0x16, 0x63, 0x1f, 0x12, 0x1a, 0x12, 0x5c, 0x2a, 0x03, 0x64, 0x1c,
        0x15, 0x40, 0x01, 0x3f, 0x4c, 0x02, 0x3a, 0x30, 0x1d, 0x7c, 0x69, 0x4d,
        0x19, 0x5f, 0x48, 0x5e, 0x20, 0x03, 0x17, 0x09, 0x52, 0x6b, 0x4c, 0x65,
        0x6f, 0x48, 0x06, 0x5b, 0x2b, 0x28, 0x40, 0x2e, 0x4e, 0x0b, 0x16, 0x31,
        0x30, 0x56, 0x21, 0x6e, 0x2d, 0x30, 0x4b, 0x1c, 0x10, 0x04, 0x3f, 0x18,
        0x41, 0x34
    ]

    def try_keystream(data, keystream):
        result = []
        for i in range(len(data)):
            result.append(data[i] ^ keystream[i % len(keystream)])
        return bytes(result)

    def check_printable(data):
        return all(c in string.printable for c in data.decode('latin1'))

    def reverse_stage3(data):
        result = bytearray(data)
        for i in range(len(result)-1, 4, -1):
            for j in range(299, -1, -1):
                result[i] = result[i] ^ ((j << 5) & 0xFF) ^ (result[i-5] == ord('n'))
        return bytes(result)

    # First attempt: try simple XOR with repeated byte keys
    print("[*] Trying single-byte XOR keys...")
    for key in range(256):
        decoded = bytes([b ^ key for b in initial_data])
        try:
            if b'flag{' in decoded or b'csawctf{' in decoded or b'CTF{' in decoded:
                print(f"\nPotential flag found with key 0x{key:02x}:")
                print(decoded.decode('ascii'))
        except:
            continue

    # Second attempt: try 4-byte XOR keys
    print("\n[*] Trying 4-byte XOR patterns...")
    common_patterns = [
        b'flag', b'ctf{', b'key:', b'pass'
    ]

    for pattern in common_patterns:
        for i in range(len(initial_data) - 3):
            key = bytes([a ^ b for a, b in zip(pattern, initial_data[i:i+4])])
            decoded = try_keystream(initial_data, key)
            try:
                if any(pat in decoded.lower() for pat in [b'flag', b'ctf', b'key']):
                    print(f"\nPotential match with pattern {pattern}:")
                    hexdump(decoded)
            except:
                continue

    # Third attempt: reverse the stages
    print("\n[*] Attempting to reverse stages...")
    stage3_data = reverse_stage3(initial_data)
    print("\nAfter reversing stage 3:")
    hexdump(stage3_data)

    # Try to find repeated sequences that might indicate key length
    print("\n[*] Looking for repeated sequences...")
    for length in range(2, 8):
        sequences = {}
        for i in range(len(initial_data) - length):
            seq = tuple(initial_data[i:i+length])
            if seq in sequences:
                sequences[seq].append(i)
            else:
                sequences[seq] = [i]

        for seq, positions in sequences.items():
            if len(positions) > 1:
                print(f"Sequence {bytes(seq).hex()} appears at positions {positions}")
                # Try using the distance between repeats as key length
                for key_length in [abs(positions[i] - positions[i-1]) for i in range(1, len(positions))]:
                    if key_length > 1:
                        print(f"Trying key length: {key_length}")
                        blocks = [initial_data[i::key_length] for i in range(key_length)]
                        # Analyze frequency in each block
                        for i, block in enumerate(blocks):
                            print(f"Block {i} most common values: {bytes([max(set(block), key=block.count)]).hex()}")

    # Try to extract the flag format from known patterns
    print("\n[*] Looking for flag format patterns...")
    for i in range(len(stage3_data) - 7):
        # Try both flag{ and csawctf{ patterns
        potential_flag = stage3_data[i:i+5]
        if any(chr(x).lower() in 'flcsawtg{' for x in potential_flag):
            print(f"Potential flag start at position {i}:")
            hexdump(stage3_data[i:i+32])

