from pwn import *

def find_flag():
    # Initial encrypted data
    encrypted = [
        0x3f, 0x42, 0x38, 0x5f, 0x7a, 0x57, 0x71, 0x74, 0x66, 0x44, 0x47, 0x32,
        0x3d, 0x16, 0x63, 0x1f, 0x12, 0x1a, 0x12, 0x5c, 0x2a, 0x03, 0x64, 0x1c,
        0x15, 0x40, 0x01, 0x3f, 0x4c, 0x02, 0x3a, 0x30, 0x1d, 0x7c, 0x69, 0x4d,
        0x19, 0x5f, 0x48, 0x5e, 0x20, 0x03, 0x17, 0x09, 0x52, 0x6b, 0x4c, 0x65,
        0x6f, 0x48, 0x06, 0x5b, 0x2b, 0x28, 0x40, 0x2e, 0x4e, 0x0b, 0x16, 0x31,
        0x30, 0x56, 0x21, 0x6e, 0x2d, 0x30, 0x4b, 0x1c, 0x10, 0x04, 0x3f, 0x18,
        0x41, 0x34
    ]

    # Based on the pattern analysis, try rolling XOR with key rotation
    def rolling_xor(data, start_key):
        result = bytearray()
        key = start_key
        for i, b in enumerate(data):
            result.append(b ^ key)
            key = (key + i) & 0xFF
        return bytes(result)

    # Try different starting keys with rolling XOR
    print("[*] Trying rolling XOR with different starting keys...")
    for start_key in range(256):
        decoded = rolling_xor(encrypted, start_key)
        try:
            if all(32 <= c <= 126 for c in decoded[:20]):  # Check if first 20 chars are printable
                print(f"\nPotential readable text with key 0x{start_key:02x}:")
                hexdump(decoded)
        except:
            continue

    # Try ROX (rotate then XOR) pattern
    def rox_decode(data, key, rotation):
        result = bytearray()
        for i, b in enumerate(data):
            rotated = ((b << rotation) | (b >> (8 - rotation))) & 0xFF
            result.append(rotated ^ key)
        return bytes(result)

    print("\n[*] Trying ROX pattern...")
    # Try a few known good rotations
    for rotation in [1, 2, 3, 4]:
        for key in [0x42, 0x3f, 0x30]:  # Most common bytes from analysis
            decoded = rox_decode(encrypted, key, rotation)
            try:
                if b'flag' in decoded.lower() or b'ctf' in decoded.lower():
                    print(f"\nPotential flag pattern found (rotation={rotation}, key=0x{key:02x}):")
                    hexdump(decoded)
            except:
                continue

    # Try block-based XOR with different block sizes
    def block_xor(data, block_size):
        result = bytearray(data)
        for i in range(len(data) - block_size):
            result[i + block_size] ^= result[i]
        return bytes(result)

    print("\n[*] Trying block-based XOR...")
    for block_size in [3, 4, 5]:  # Common block sizes
        decoded = block_xor(encrypted, block_size)
        try:
            if any(c in decoded for c in b'flagct{}'):
                print(f"\nPotential pattern found with block size {block_size}:")
                hexdump(decoded)
        except:
            continue

    # Try XOR with pattern from most common bytes
    common_bytes = [0x30, 0x3f, 0x40, 0x42]
    key_pattern = bytes(common_bytes)

    print("\n[*] Trying pattern-based XOR...")
    result = bytearray()
    for i, b in enumerate(encrypted):
        result.append(b ^ key_pattern[i % len(key_pattern)])

    print("\nPattern XOR result:")
    hexdump(bytes(result))

    # Try reverse ROX (right rotate then XOR)
    def reverse_rox(data, key, rotation):
        result = bytearray()
        for i, b in enumerate(data):
            rotated = ((b >> rotation) | (b << (8 - rotation))) & 0xFF
            result.append(rotated ^ key)
        return bytes(result)

    print("\n[*] Trying reverse ROX pattern...")
    # Use patterns from previous analysis
    for rotation in [1, 2, 3, 4]:
        for key in [0x3f, 0x42, 0x30]:  # Most frequent bytes
            decoded = reverse_rox(encrypted, key, rotation)
            if any(x in decoded for x in [b'flag', b'ctf', b'key']):
                print(f"\nPotential flag (reverse ROX rotation={rotation}, key=0x{key:02x}):")
                hexdump(decoded)

    # Try using the 'n' character pattern found in stage 3
    def stage3_decode(data):
        result = bytearray(data)
        for i in range(len(result)-1, 4, -1):
            n_check = result[i-5] == ord('n')
            for j in range(255, -1, -1):
                current = result[i]
                shifted = (j << 5) & 0xFF
                if (current ^ shifted ^ n_check) in range(32, 127):
                    result[i] = current ^ shifted ^ n_check
                    break
        return bytes(result)

    print("\n[*] Trying stage 3 decode with 'n' pattern...")
    decoded = stage3_decode(encrypted)
    hexdump(decoded)

