#!/usr/bin/env python3
from pwn import *
import string
import subprocess

def test_input(binary_path, input_str):
    print(f"\nTesting input: {input_str}")
    try:
        p = process([binary_path, input_str])
        output = p.recvall().decode(errors='ignore')
        p.close()
        print(f"Output: {output}")
        return output
    except Exception as e:
        print(f"Output: {str(e)}")
        return str(e)

def run_strace(binary_path, input_str):
    print(f"\nRunning strace with input: {input_str}")
    try:
        cmd = ['strace', binary_path, input_str]
        result = subprocess.run(cmd, capture_output=True, text=True)
        return result.stderr
    except Exception as e:
        return str(e)

def main():
    binary_path = '/home/ctfplayer/ctf_files/chal/food'

    print("Testing basic patterns:")
    test_cases = [
        "test",
        "flag{test}",
        "A"*20,
        "n"*20,
        "flag{" + "A"*20 + "}",
        string.printable
    ]

    for test in test_cases:
        test_input(binary_path, test)

    print("\nTesting various lengths:")
    for length in range(10, 70, 10):
        print(f"\nTesting length {length}")
        test_input(binary_path, "A" * length)

    print("\nTesting 'n' character variations:")
    n_tests = [
        "n"*5,
        "nnn" + "A" + "nnnn",
        "AAA" + "nnnn" + "AAA"
    ]

    for test in n_tests:
        test_input(binary_path, test)

    print("\nRunning strace analysis:")
    strace_output = run_strace(binary_path, "test")
    print(strace_output)

if __name__ == "__main__":
    main()

